import { createWorkspace, teardownWorkspace } from "@tigrisdata/agent-kit";
import { S3Client, PutObjectCommand } from "@aws-sdk/client-s3";

async function main() {
  const workspaceName = "scoped-upload-ws";
  let workspace;

  try {
    const response = await createWorkspace(workspaceName, { credentials: { role: "Editor" } });

    if (response.error) {
      throw response.error;
    }

    workspace = response.data;

    if (!workspace.bucket) {
      throw new Error("Workspace bucket is missing from response.");
    }

    if (!workspace.credentials || !workspace.credentials.accessKeyId || !workspace.credentials.secretAccessKey) {
      throw new Error("Workspace credentials are missing from response.");
    }

    const s3Client = new S3Client({
      region: "REDACTED",
      endpoint: "REDACTED",
      credentials: {
        accessKeyId: workspace.credentials.accessKeyId,
        secretAccessKey: workspace.credentials.secretAccessKey,
      },
    });

    const putCmd = new PutObjectCommand({
      Bucket: workspace.bucket,
      Key: "greeting.txt",
      Body: "hello scoped",
    });

    await s3Client.send(putCmd);

    console.log(`SCOPED_UPLOAD_OK ${workspace.bucket}`);
  } catch (error) {
    console.error("Error during workspace upload:", error);
    process.exit(1);
  } finally {
    if (workspace) {
      await teardownWorkspace(workspace);
    }
  }
}

main();

